class Solution {
  public int maxDigitRange(int[] nums) {
    int bestRange = -1, sum = 0;
    for (int x : nums) {
      int max = 0, min = 9;
      for (int y = x; y > 0; y /= 10) {
        max = Math.max(max, y % 10);
        min = Math.min(min, y % 10);
      }
      int range = max - min;
      if (range > bestRange) {
        bestRange = range;
        sum = x;
      } else if (range == bestRange) {
        sum += x;
      }
    }
    return sum;
  }
}
